<script setup lang="ts">
import {localize} from './localization';

import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import ToolIcon from './ToolIcon.vue';
import {cameraBox,parseViewBox,zoomCamera,minimumZoom,maximumZoom} from '../../../packages/ui/viewport';
const props=defineProps<{viewBox:string;focusBox?:string;hideInteractionTools?:boolean;label:string;language:'zh'|'en';drawing?:boolean;interaction?:'pan'|'edit'}>();
const emit=defineEmits<{interaction:[value:'pan'|'edit']}>();
const content=ref<HTMLElement>(),camera=ref({zoom:1,panX:0,panY:0}),hand=ref(false),space=ref(false);
watch(()=>props.interaction,value=>{if(value)hand.value=value==='pan';},{immediate:true});
function setHand(value:boolean){hand.value=value;emit('interaction',value?'pan':'edit');}
const zh=computed(()=>props.language==='zh'),base=computed(()=>parseViewBox(props.viewBox)),box=computed(()=>{const b=cameraBox(base.value,camera.value);return `${b.x} ${b.y} ${b.width} ${b.height}`;});
let pan:{pointerId:number;inverse:DOMMatrix;start:DOMPoint;panX:number;panY:number}|undefined;
function svg(){return content.value?.querySelector('svg');}
function endPan(){const id=pan?.pointerId;pan=undefined;if(id!==undefined&&content.value?.hasPointerCapture(id))content.value.releasePointerCapture(id);}
function reset(force=false){if(props.drawing&&!force)return;endPan();camera.value={zoom:1,panX:0,panY:0};}
function focus(){if(!props.focusBox||props.drawing||pan)return;const target=parseViewBox(props.focusBox),b=base.value;camera.value={zoom:Math.max(minimumZoom,Math.min(maximumZoom,Math.min(b.width/target.width,b.height/target.height)/1.12)),panX:target.x+target.width/2-b.x-b.width/2,panY:target.y+target.height/2-b.y-b.height/2};}
watch(()=>props.viewBox,()=>{reset(true);focus();},{immediate:true});
// Dismissing a detail or starting a blank-area gesture must preserve the camera.
watch(()=>props.focusBox,value=>{if(value)focus();},{immediate:true});
function zoom(factor:number,event?:WheelEvent){if(props.drawing||pan)return;const matrix=svg()?.getScreenCTM(),anchor=event&&matrix?new DOMPoint(event.clientX,event.clientY).matrixTransform(matrix.inverse()):undefined;camera.value=zoomCamera(base.value,camera.value,factor,anchor);}
function setZoom(event:Event){const value=Number((event.target as HTMLInputElement).value);if(Number.isFinite(value)&&value>0)zoom(value/100/camera.value.zoom);}
function down(event:PointerEvent){content.value?.focus({preventScroll:true});if(event.button!==1&&!(event.button===0&&!props.drawing&&(hand.value||space.value)))return;const matrix=svg()?.getScreenCTM();if(!matrix)return;event.preventDefault();event.stopImmediatePropagation();const inverse=matrix.inverse();pan={pointerId:event.pointerId,inverse,start:new DOMPoint(event.clientX,event.clientY).matrixTransform(inverse),panX:camera.value.panX,panY:camera.value.panY};content.value?.setPointerCapture(event.pointerId);}
function move(event:PointerEvent){if(!pan||pan.pointerId!==event.pointerId)return;event.preventDefault();event.stopImmediatePropagation();const point=new DOMPoint(event.clientX,event.clientY).matrixTransform(pan.inverse);camera.value={...camera.value,panX:pan.panX-(point.x-pan.start.x),panY:pan.panY-(point.y-pan.start.y)};}
function up(event:PointerEvent){if(!pan||pan.pointerId!==event.pointerId)return;event.preventDefault();event.stopImmediatePropagation();endPan();}
function key(event:KeyboardEvent){if(event.key===' '){event.preventDefault();event.stopPropagation();space.value=event.type==='keydown';}if(event.type==='keydown'&&['+','=','-','0'].includes(event.key)){event.preventDefault();event.stopPropagation();if(event.key==='0')reset();else zoom(event.key==='-'?1/1.25:1.25);}}
function blur(){space.value=false;endPan();}
onMounted(()=>window.addEventListener('blur',blur));onUnmounted(()=>{window.removeEventListener('blur',blur);blur();});
</script>
<template><section class="zoom-viewport" role="region" :aria-label="label+' viewport'">
 <div class="zoom-toolbar"><label class="zoom-percentage"><input :disabled="drawing" type="number" :value="Math.round(camera.zoom*100)" min="10" max="3200" step="10" :aria-label="zh?'预览缩放百分比':localize('Preview zoom percent')" @change="setZoom">%</label><small>{{zh?'滚轮缩放 · 中键拖动平移':localize('Wheel zoom · Middle drag to pan')}}</small></div>
 <div class="zoom-workarea"><nav class="zoom-rail" :aria-label="zh?'二维视图工具':localize('2D view tools')"><button v-if="!hideInteractionTools" :disabled="drawing" :class="{active:!hand}" :aria-pressed="!hand" :title="zh?'选择 / 编辑':localize('Select / edit')" :aria-label="zh?'选择 / 编辑':localize('Select / edit')" @click="setHand(false)"><ToolIcon name="select"/></button><button v-if="!hideInteractionTools" :disabled="drawing" :class="{active:hand}" :aria-pressed="hand" :title="zh?'手形平移':localize('Pan tool')" :aria-label="zh?'手形平移':localize('Pan tool')" @click="setHand(true)"><ToolIcon name="pan"/></button><slot name="rail"/><button :disabled="drawing" :title="zh?'放大':localize('Zoom in')" :aria-label="zh?'放大':localize('Zoom in')" @click="zoom(1.25)"><ToolIcon name="zoomIn"/></button><button :disabled="drawing" :title="zh?'缩小':localize('Zoom out')" :aria-label="zh?'缩小':localize('Zoom out')" @click="zoom(1/1.25)"><ToolIcon name="zoomOut"/></button><button :disabled="drawing" :title="zh?'适合窗口':localize('Fit view')" :aria-label="zh?'适合窗口':localize('Fit view')" @click="reset()"><ToolIcon name="fit"/></button></nav>
 <div ref="content" class="zoom-content" :class="{hand:hand||space}" tabindex="0" :aria-label="label+' interaction'" @wheel.prevent.stop="zoom(Math.exp(Math.max(-300,Math.min(300,-$event.deltaY))*.002),$event)" @pointerdown.capture="down" @pointermove.capture="move" @pointerup.capture="up" @pointercancel.capture="up" @lostpointercapture="pan=undefined" @keydown="key" @keyup="key" @blur="blur"><slot :view-box="box"/></div></div>
</section></template>
<style scoped>.zoom-viewport{min-width:0;width:100%}.zoom-toolbar{display:flex;align-items:center;gap:6px;flex-wrap:wrap;padding:7px 0}.zoom-percentage{display:flex;align-items:center;gap:3px;margin:0;font-size:11px}.zoom-percentage input{width:68px;padding:4px;font-size:11px}.zoom-toolbar small{color:var(--text-muted);font-size:10px}.zoom-workarea{display:flex;align-items:stretch;min-width:0}.zoom-rail{height:auto;max-height:clamp(160px,calc(100dvh - 320px),780px);width:50px;align-self:flex-start;overflow-y:auto;overflow-x:hidden;align-items:stretch;display:flex;flex-direction:column;gap:4px;padding:4px;flex:none;border-right:1px solid var(--border);background:var(--panel)}.zoom-rail button,.zoom-rail :deep(button){padding:7px;flex:none;min-height:35px;width:34px;max-width:100%;display:grid;place-items:center;border-radius:var(--radius-control)}.zoom-rail :deep(fieldset){flex:none;min-width:0}.zoom-rail::-webkit-scrollbar{width:5px}.zoom-rail::-webkit-scrollbar-thumb{background:var(--border);border-radius:4px}.zoom-content{overflow:hidden;min-width:0;flex:1;touch-action:none;outline:none}.zoom-content:focus-visible{outline:1px solid var(--accent);outline-offset:2px}.zoom-content.hand :deep(svg){cursor:grab!important}.zoom-content :deep(svg){display:block;width:100%;touch-action:none}.zoom-content :deep(image){pointer-events:none}.zoom-content :deep(.selection-overlay){vector-effect:non-scaling-stroke}</style>
